```yaml
name: Pre-commit Execute
on:
  issue_comment:
    types: [created]
permissions:
  contents: read
  pull-requests: read

jobs:
  validate-trigger:
    if: github.event.comment.body == '@github-actions run precommit'
    runs-on: ubuntu-latest
    steps:
      - name: Check if comment is from PR author or collaborator
        id: check-permissions
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { data: comment } = await github.rest.issues.getComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              comment_id: context.payload.comment.id
            });

            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: comment.issue_url.split('/').pop()
            });

            const { data: collaboration } = await github.rest.repos.getCollaboratorPermissionLevel({
              owner: context.repo.owner,
              repo: context.repo.repo,
              username: comment.user.login
            });

            const isAuthor = comment.user.login === pr.user.login;
            const isCollaborator = collaboration.permission !== 'read';

            if (!isAuthor && !isCollaborator) {
              core.setFailed('Only PR author or repository collaborators can trigger pre-commit');
            }

            core.setOutput('pr-number', pr.number);
            core.setOutput('branch-name', pr.head.ref);
            core.setOutput('repo-owner', context.repo.owner);
            core.setOutput('repo-name', context.repo.repo);

      - name: Cancel previous runs
        uses: styfle/cancel-workflow-action@0.12.1
        with:
          workflow_id: precommit-execute.yml
          access_token: ${{ secrets.GITHUB_TOKEN }}

      - name: Dispatch execution workflow
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            await github.rest.actions.createWorkflowDispatch({
              owner: context.repo.owner,
              repo: context.repo.repo,
              workflow_id: 'precommit-execute-execution.yml',
              ref: 'main',
              inputs: {
                pr_number: '${{ steps.check-permissions.outputs.pr-number }}',
                branch_name: '${{ steps.check-permissions.outputs.branch-name }}',
                repo_owner: '${{ steps.check-permissions.outputs.repo-owner }}',
                repo_name: '${{ steps.check-permissions.outputs.repo-name }}'
              }
            });

  execute-precommit:
    needs: validate-trigger
    if: always() && needs.validate-trigger.result == 'success'
    runs-on: ubuntu-latest
    permissions:
      contents: write
      pull-requests: write
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          ref: ${{ github.event.inputs.branch_name }}
          token: ${{ secrets.GITHUB_TOKEN }}

      - name: Set up Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.11'

      - name: Install pre-commit
        run: |
          pip install pre-commit

      - name: Run pre-commit hooks
        id: precommit
        uses: pre-commit/action@v3.0.1
        with:
          extra_args: --all-files

      - name: Commit and push changes
        if: steps.precommit.outcome == 'failure'
        uses: EndBug/add-and-commit@v9
        with:
          message: 'Automated pre-commit fixes'
          author_name: 'github-actions[bot]'
          author_email: 'github-actions[bot]@users.noreply.github.com'
          push: true
          branch: ${{ github.event.inputs.branch_name }}
          cwd: .

      - name: Comment on PR
        if: always()
        uses: thollander/actions-comment-pull-request@e4a76dd2b0a3c2027c3fd84147a67c22ee4c90fa
        with:
          message: |
            Pre-commit execution completed.
            ${{ steps.precommit.outcome == 'failure' && 'Changes were committed to the PR branch.' || 'No changes required.' }}
          github-token: ${{ secrets.GITHUB_TOKEN }}
          pr-number: ${{ github.event.inputs.pr_number }}
